namespace SpeedStars.Editor {
 public static partial class ThemeKitBuilder {
  static void ThemeDoor(Transform t,Vector3 p,float w,float h){Box(t,"Recessed Timber Door",p+Vector3.up*h*.5f,new Vector3(w,h,.14f),woodDark);for(int i=0;i<5;i++)Box(t,"Door Vertical Board",p+new Vector3((i-2)*w/5,h*.5f,-.09f),new Vector3(w/5-.025f,h-.1f,.07f),wood);foreach(float y in new[]{h*.2f,h*.8f})Box(t,"Door Iron Strap",p+new Vector3(0,y,-.14f),new Vector3(w,.08f,.04f),dark);}
  static void WorkshopShell(Transform t,float w,float h,float depth,Material wall,bool flat){Box(t,"Continuous Wall Body",new Vector3(0,h*.5f,0),new Vector3(w,h,depth),wall);Box(t,"Grounded Stone Footing",new Vector3(0,.18f,0),new Vector3(w+.2f,.36f,depth+.2f),sandLight);if(flat){Box(t,"Flat Roof Slab",new Vector3(0,h+.12f,0),new Vector3(w+.4f,.24f,depth+.4f),sandLight);foreach(float x in new[]{-w*.5f,w*.5f})Box(t,"Roof Side Parapet",new Vector3(x,h+.4f,0),new Vector3(.24f,.5f,depth),wall);}else{var roof=Pyramid(t,"Hipped Tile Roof",new Vector3(0,h,0),w+.7f,1.6f,red);roof.transform.localScale=new Vector3(1,1,(depth+.7f)/(w+.7f));}ThemeDoor(t,new Vector3(-w*.2f,0,-depth*.5f-.05f),1.25f,2.25f);Box(t,"Shop Window Recess",new Vector3(w*.27f,2,-depth*.5f-.04f),new Vector3(1.1f,1.1f,.09f),dark);Box(t,"Stone Window Sill",new Vector3(w*.27f,1.4f,-depth*.5f-.15f),new Vector3(1.4f,.15f,.3f),sandLight);}
  static void PlankedPier(Transform t,float w,float depth){for(int i=0;i<Mathf.CeilToInt(w/.55f);i++)Box(t,"Individual Pier Board",new Vector3(-w*.5f+.275f+i*.55f,.4f,0),new Vector3(.51f,.22f,depth),i%3==0?woodDark:wood);foreach(float x in new[]{-w*.45f,w*.45f})foreach(float z in new[]{-depth*.43f,depth*.43f})Cylinder(t,"Sea Bed Timber Pile",new Vector3(x,-1.6f,z),.19f,2.3f,woodDark,10);foreach(float z in new[]{-depth*.4f,depth*.4f})Box(t,"Pier Structural Crossbeam",new Vector3(0,.23f,z),new Vector3(w+.2f,.26f,.25f),woodDark);}
  static void MerchantJars(Transform t,Vector3 p,int count){for(int i=0;i<count;i++)TradeJar(t,p+new Vector3(i*.85f,0,0),i%2==0?sand:red);}
  static void AddThemeAssets(LoopThemeDefinition d,IEnumerable<GameObject> models,IEnumerable<GameObject> props){var a=d.landmarks.Where(x=>x).ToList();foreach(var m in models){a.RemoveAll(x=>x.name==m.name);a.Add(m);}d.landmarks=a.ToArray();var b=d.props.Where(x=>x).ToList();foreach(var m in props){b.RemoveAll(x=>x.name==m.name);b.Add(m);}d.props=b.ToArray();EditorUtility.SetDirty(d);}
  static void ExpandThemeHorizon(LoopThemeDefinition d,bool sky){
   var far=new List<GameObject>();
   if(sky){
    far.Add(Model("Horizon Sky Twin Spires",t=>{Island(t,true);foreach(float x in new[]{-2.5f,2.5f}){Cylinder(t,"Distant Tower",new Vector3(x,.3f,0),.9f,4.8f,cream,10);Lathe(t,"Distant Spire",new Vector3(x,5.1f,0),new[]{0f,2.3f},new[]{1.2f,.01f},teal,10);}Arc(t,"Bridge Between Spires",new Vector3(0,2.2f,0),2,.35f,.6f,stone,14);}));
    far.Add(Model("Horizon Sky Ancient Ring Ruins",t=>{Island(t,true);for(int i=0;i<6;i++){float a=i*Mathf.PI/3;Cylinder(t,"Ruined Ring Pillar",new Vector3(Mathf.Sin(a)*3,.3f,Mathf.Cos(a)*3),.32f,2.2f+i%3*.7f,stone,10);}var r=new GameObject("Tilted Ancient Ring");r.transform.SetParent(t,false);r.transform.localPosition=Vector3.up*2.8f;Arc(r.transform,"Half Buried Rune Ring",Vector3.zero,2.3f,.35f,.5f,cream,24,0,285);}));
   }else{
    far.Add(Model("Horizon Sea Fortified Harbor",t=>{Lathe(t,"Harbor Stone Island",new Vector3(0,-.5f,0),new[]{0f,.8f,1.2f},new[]{8,7.6f,6.8f},stone,14);Box(t,"Harbor Rampart",new Vector3(0,2,0),new Vector3(11,2.5f,2),cream);foreach(float x in new[]{-5f,5f}){Cylinder(t,"Harbor Fort Tower",new Vector3(x,.7f,0),1.2f,4.4f,stone,12);for(int i=0;i<6;i++){float a=i*Mathf.PI/3;Box(t,"Fort Crenellation",new Vector3(x+Mathf.Sin(a),5.3f,Mathf.Cos(a)),new Vector3(.45f,.5f,.45f),cream);}}Box(t,"Far Port Gate",new Vector3(0,1.6f,-1.04f),new Vector3(1.8f,2,.08f),woodDark);}));
    far.Add(Model("Horizon Sea Hillside Roof Quarter",t=>{Lathe(t,"Coastal Rock Shelf",new Vector3(0,-.5f,0),new[]{0f,1.2f,1.6f},new[]{9f,8f,7f},sandLight,14);for(int i=0;i<5;i++){float x=-5+i*2.5f,h=2+(i%3)*.8f;Box(t,"Far Coastal House",new Vector3(x,1.5f+h*.5f,0),new Vector3(2.2f,h,2.8f),i%2==0?cream:blue);var roof=Pyramid(t,"Far Coastal Roof",new Vector3(x,1.5f+h,0),2.6f,1.2f,red);roof.transform.localScale=new Vector3(1,1,1.25f);Box(t,"Single Dark Window",new Vector3(x,2.6f,-1.45f),new Vector3(.5f,.6f,.05f),dark);}}));
   }
   var all=d.background.Where(p=>p).ToList();foreach(var source in far){var faded=Background(source,source.name+" Haze");all.RemoveAll(p=>p.name==faded.name);all.Add(faded);}d.background=all.ToArray();EditorUtility.SetDirty(d);
  }
  public static string ExpandEgyptTrades(){
