   models.Add(RomanQualityModel("Desert Trade Reed Weaver House",t=>{WorkshopShell(t,5.6f,3.3f,4.2f,cream,true);RCanopy(t,new Vector3(0,0,-2.2f),6.6f,2.8f,sand);foreach(float x in new[]{-1.6f,1.6f})Box(t,"Loom Grounded Upright",new Vector3(x,1.5f,-3.1f),new Vector3(.17f,3,.17f),woodDark);foreach(float y in new[]{.4f,2.9f})Beam(t,"Loom Crossbar",new Vector3(-1.6f,y,-3.1f),new Vector3(1.6f,y,-3.1f),.14f,woodDark);for(int i=0;i<15;i++)Beam(t,"Loom Warp Thread",new Vector3(-1.4f+i*.2f,.4f,-3.1f),new Vector3(-1.4f+i*.2f,2.9f,-3.1f),.022f,cream);for(int i=0;i<8;i++)Box(t,"Woven Reed Bands",new Vector3(0,.6f+i*.15f,-3.13f),new Vector3(2.85f,.10f,.05f),i%3==0?red:sand);for(int i=0;i<3;i++)Lathe(t,"Woven Storage Basket",new Vector3(3.6f,0,-2.5f+i*.9f),new[]{0f,.7f,.9f},new[]{.35f,.45f,.42f},wood,12);}));
   models.Add(RomanQualityModel("Desert Trade Scribe Archive House",t=>{WorkshopShell(t,4.8f,5.5f,4.5f,sand,true);var wing=new GameObject("Low Archive Wing");wing.transform.SetParent(t,false);wing.transform.localPosition=new Vector3(4,0,.6f);WorkshopShell(wing.transform,3.2f,2.8f,4,cream,true);for(int i=0;i<4;i++)Box(t,"Archive Roof Timber Ends",new Vector3(-1.8f+i*1.2f,5.35f,-2.55f),new Vector3(.15f,.15f,.7f),woodDark);TradeTable(t,new Vector3(0,0,-3.1f),3);for(int i=0;i<5;i++){var scroll=Cylinder(t,"Rolled Papyrus",new Vector3(-1+i*.5f,1.47f,-3.4f),.10f,.65f,cream,10);scroll.transform.localRotation=Quaternion.Euler(90,0,0);}Box(t,"Scribe Ochre Sign",new Vector3(1.6f,3.4f,-2.31f),new Vector3(1,.7f,.12f),gold);for(int i=0;i<3;i++)Box(t,"Carved Archive Glyph",new Vector3(1.35f+i*.23f,3.4f,-2.39f),new Vector3(.07f,.4f,.03f),teal);}));
   var supplies=RomanQualityModel("Desert Trade Dye Jar Stand",t=>{TradeTable(t,Vector3.zero,2.4f);MerchantJars(t,new Vector3(-.85f,1.34f,0),3);});AddThemeAssets(d,models,new[]{supplies});ApplyRomanPixelPaint();AssetDatabase.SaveAssets();System.IO.File.WriteAllText("Docs/EgyptTradeVarietyAudit.md",string.Join("\n",egyptAudit.ToArray()));return "Egypt: "+d.landmarks.Length+" structures";
